def match_fee(tx, fee, merchant_chars):
    """
    Check if a transaction matches a fee rule.
    tx: transaction series
    fee: fee dict
    merchant_chars: dict with account_type, mcc, capture_delay, monthly_fraud_level, monthly_volume
    """
    # card_scheme
    if fee['card_scheme'] is not None and fee['card_scheme'] != tx['card_scheme']:
        return False

    # account_type
    if fee['account_type'] is not None and len(fee['account_type']) > 0:
        if merchant_chars['account_type'] not in fee['account_type']:
            return False

    # capture_delay - need to interpret merchant capture_delay value
    if fee['capture_delay'] is not None:
        cd = merchant_chars['capture_delay']
        if cd == 'immediate' or cd == 'manual':
            if fee['capture_delay'] != cd:
                return False
        elif cd in ('1', '2'):
            if fee['capture_delay'] != '<3':
                return False
        elif cd == '7':
            if fee['capture_delay'] != '>5':
                return False
        elif cd == '3-5':
            if fee['capture_delay'] != '3-5':
                return False
        else:
            # unknown value
            return False

    # monthly_fraud_level
    if fee['monthly_fraud_level'] is not None:
        if merchant_chars['monthly_fraud_level'] != fee['monthly_fraud_level']:
            return False

    # monthly_volume
    if fee['monthly_volume'] is not None:
        if merchant_chars['monthly_volume'] != fee['monthly_volume']:
            return False

    # merchant_category_code
    if fee['merchant_category_code'] is not None and len(fee['merchant_category_code']) > 0:
        if merchant_chars['merchant_category_code'] not in fee['merchant_category_code']:
            return False

    # is_credit
    if fee['is_credit'] is not None:
        if fee['is_credit'] != tx['is_credit']:
            return False

    # aci
    if fee['aci'] is not None and len(fee['aci']) > 0:
        if tx['aci'] not in fee['aci']:
            return False

    # intracountry
    if fee['intracountry'] is not None:
        ic = (tx['issuing_country'] == tx['acquirer_country'])
        if fee['intracountry'] != ic:
            return False

    return True

