# Empty list = wildcard (same as null)
# Single winning rule: highest specificity (count of constrained fields), tie-break by smallest ID

def get_constrained_count(fee):
    """Count constrained fields: non-null scalars, and non-null non-empty lists."""
    count = 0
    # Scalar fields
    for field in ['card_scheme', 'capture_delay', 'is_credit', 'intracountry', 'monthly_volume', 'monthly_fraud_level']:
        if fee[field] is not None:
            count += 1
    # List fields: constrained only if non-null and non-empty
    for field in ['account_type', 'merchant_category_code', 'aci']:
        if fee[field] is not None and len(fee[field]) > 0:
            count += 1
    return count

